import sqlite3
import json
from sentence_transformers import SentenceTransformer
from pymilvus import connections, Collection

# Configuration
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db"
}

milvus_config = {
    'collections': {
        'reviews': 'reviews',
        'tips': 'milvus_tip'
    },
    'host': 'localhost',
    'port': '19530'
}

# Step 1: Get Tampa auto repair businesses
conn_business = sqlite3.connect(sqlite_paths['business'])
cursor_business = conn_business.cursor()

try:
    cursor_business.execute('''
        SELECT business_id, name, address, stars, review_count 
        FROM business 
        WHERE city = ? AND categories LIKE ?
    ''', ('Tampa', '%Auto Repair%'))
    tampa_auto_repair_businesses = cursor_business.fetchall()
    business_ids = [row[0] for row in tampa_auto_repair_businesses]
    business_dict = {row[0]: {'name': row[1], 'address': row[2], 'stars': row[3], 'review_count': row[4]} for row in tampa_auto_repair_businesses}
except Exception as e:
    print(f"Error querying business DB: {e}")
    tampa_auto_repair_businesses = []
    business_ids = []
    business_dict = {}
finally:
    conn_business.close()

if not business_ids:
    print("No auto repair shops found in Tampa.")
else:
    # Step 2: Vector search for 'honest and fair pricing'
    connections.connect(host=milvus_config['host'], port=milvus_config['port'])
    model = SentenceTransformer('all-MiniLM-L6-v2')
    query_text = "honest and fair pricing"
    query_embedding = model.encode([query_text])[0].tolist()

    relevant_business_ids = set()

    try:
        # Search reviews
        reviews_collection = Collection(milvus_config['collections']['reviews'])
        reviews_results = reviews_collection.search(
            data=[query_embedding],
            anns_field="vector",
            param={"metric_type": "L2", "params": {"nprobe": 10}},
            limit=50,
            output_fields=["business_id"]
        )
        for hits in reviews_results:
            for hit in hits:
                if hit.entity.get('business_id') in business_ids:
                    relevant_business_ids.add(hit.entity.get('business_id'))

        # Search tips
        tips_collection = Collection(milvus_config['collections']['tips'])
        tips_results = tips_collection.search(
            data=[query_embedding],
            anns_field="vector",
            param={"metric_type": "L2", "params": {"nprobe": 10}},
            limit=50,
            output_fields=["business_id"]
        )
        for hits in tips_results:
            for hit in hits:
                if hit.entity.get('business_id') in business_ids:
                    relevant_business_ids.add(hit.entity.get('business_id'))

    except Exception as e:
        print(f"Error during Milvus search: {e}")
        relevant_business_ids = set()
    finally:
        connections.disconnect('default')

    # Step 3: Combine results
    honest_shops = []
    for bid in relevant_business_ids:
        if bid in business_dict:
            honest_shops.append({
                'business_id': bid,
                **business_dict[bid]
            })

    # Sort by star rating and review count for better ranking
    honest_shops.sort(key=lambda x: (-x['stars'], -x['review_count']))

    print("\nHonest auto repair shops in Tampa with fair pricing (based on review semantics):")
    for shop in honest_shops:
        print(f"- {shop['name']} | Stars: {shop['stars']} | Reviews: {shop['review_count']} | Address: {shop['address']}")

    if not honest_shops:
        print("No shops matched the criteria for honesty and fair pricing in reviews/tips.")
